using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps.EditorTools;
public static class Shore96Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static void Check(bool b,string s){if(!b)throw new Exception(s);}
 public static void Run(){int exit=0;var output=Path.Combine(Root,"Evidence96Import");Directory.CreateDirectory(output);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var shader=Shader.Find("MapSharedProps/Lit");Check(shader&&shader.isSupported,"standard shared shader");Texture shared=null;int triangles=0;long textureBytes=0;
 foreach(var kind in new[]{"before","after","absent","badUV","badPNG","oldReader"}){string input=Path.Combine(Root,"Input96-"+(kind=="oldReader"?"after":kind)),folder="Assets/Shore96v5-"+kind;if(!AssetDatabase.IsValidFolder(folder))AssetDatabase.CreateFolder("Assets","Shore96v5-"+kind);var parent=new GameObject("Isolated shore fixture");int count=kind=="oldReader"?FrozenShoreReader95.Build(input,folder,parent.transform,shader):GroundedPropsV1.Build(input,folder,parent.transform,shader);Check(count==1&&parent.transform.childCount==1,"one placed cluster "+kind);var o=parent.transform.GetChild(0).gameObject;Check(o.GetComponentsInChildren<Collider>().Length==0,"nonblocking shore collider "+kind);Check(o.GetComponentsInChildren<Renderer>().Length==1,"one combined renderer "+kind);var m=o.GetComponent<MeshFilter>().sharedMesh;var mat=o.GetComponent<MeshRenderer>().sharedMaterial;Check(!ShaderUtil.ShaderHasError(mat.shader),"shader "+kind);
 var data=GroundedPropsV1.Read(Path.Combine(input,"grounded_props.json"));Check(data.assets[0].parts.Length==9,"nine stable parts");var source=data.instances[0];int offset=0;float max=0;foreach(var part in data.assets[0].parts){var pose=Array.Find(source.parts,p=>p.id==part.id);var transform=Matrix4x4.TRS(new Vector3(pose.position[0],pose.position[1],pose.position[2]),new Quaternion(pose.rotation[0],pose.rotation[1],pose.rotation[2],pose.rotation[3]),new Vector3(pose.scale[0],pose.scale[1],pose.scale[2]));for(int k=0;k<part.positions.Length/3;k++){var expected=transform.MultiplyPoint3x4(new Vector3(part.positions[k*3],part.positions[k*3+1],part.positions[k*3+2]));max=Mathf.Max(max,Vector3.Distance(expected,o.transform.TransformPoint(m.vertices[offset+k])));}offset+=part.positions.Length/3;}Check(max<.00002f,"exported world pose "+kind);
 if(kind=="after"){triangles=m.triangles.Length/3;Check(triangles<2000,"mesh budget");shared=mat.GetTexture("_BaseMap");Check(shared&&shared.width==128&&shared.height==128,"shared 128px atlas");textureBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(shared);Check(m.uv.Any(v=>v.x>.5f)&&m.uv.Any(v=>v.x<.5f),"both atlas regions");PrefabUtility.SaveAsPrefabAsset(o,"Assets/shore96-after.prefab");}
 else {var tex=mat.GetTexture("_BaseMap");Check(tex==null||tex==Texture2D.whiteTexture,"optional white default fallback "+kind);}
 if(kind=="before")PrefabUtility.SaveAsPrefabAsset(o,"Assets/shore96-before.prefab");UnityEngine.Object.DestroyImmediate(parent);}
 var p2=new GameObject("Shared texture reuse");string f2="Assets/Shore96v5-repeat";if(!AssetDatabase.IsValidFolder(f2))AssetDatabase.CreateFolder("Assets","Shore96v5-repeat");GroundedPropsV1.Build(Path.Combine(Root,"Input96-after"),f2,p2.transform,shader);Check(p2.GetComponentInChildren<Renderer>().sharedMaterial.GetTexture("_BaseMap")==shared,"texture cache reuse");UnityEngine.Object.DestroyImmediate(p2);AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"cases\":[\"before\",\"after\",\"absent\",\"badUV\",\"badPNG\",\"oldReader\"],\"nineStableParts\":true,\"oneRenderer\":true,\"colliders\":0,\"worldPoseToleranceMetres\":0.00002,\"triangles\":"+triangles+",\"textureRuntimeBytes\":"+textureBytes+",\"textureShared\":true,\"playerExecuted\":false}");
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
